 19 │ import * as fs from "node:fs";
 20 │ import * as path from "node:path";
 21 │ import { envWithoutConfiguredHooks } from "../core/git_hook_guard.js";
 22 │ import { PATHSPEC_MODE_ENV } from "../git.js";
 23 │ import { redactSecrets } from "../ui.js";
 24 │ 
 25 │ /** Hook events Nexus-initiated worktree commands must never fire. */
 26 │ export const SUPPRESSED_HOOK_EVENTS = [
 27 │   "post-checkout", "pre-commit", "prepare-commit-msg", "commit-msg", "post-commit", "post-merge",
 28 │   "pre-merge-commit", "pre-rebase", "post-rewrite", "reference-transaction", "post-index-change", "pre-auto-gc",
 29 │ ] as const;
 30 │ 
 31 │ export const PINNED_GIT_FLAGS: readonly string[] = [
 32 │   "--no-replace-objects",
 33 │   "--no-optional-locks",
 34 │   "-c", "core.hooksPath=/dev/null",
 35 │   "-c", "core.fsmonitor=false",
 36 │   "-c", "protocol.ext.allow=never",
 37 │   "-c", "submodule.recurse=false",
 38 │   "-c", "core.quotePath=false",
 39 │ ];
 40 │ 
 41 │ /** Variables that would redirect Git at another repository, object store, diff driver or ref namespace, or change how pathspecs are read. */
 42 │ export const SCRUBBED_ENV = [
 43 │   "GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY", "GIT_ALTERNATE_OBJECT_DIRECTORIES",
 44 │   "GIT_COMMON_DIR", "GIT_NAMESPACE", "GIT_EXTERNAL_DIFF", "GIT_REPLACE_REF_BASE", "GIT_PAGER", "GIT_SSH_COMMAND",
 45 │   "GIT_ASKPASS", "GIT_EDITOR", "GIT_SEQUENCE_EDITOR", "GIT_PREFIX", "GIT_CEILING_DIRECTORIES",
 46 │   ...PATHSPEC_MODE_ENV,
 47 │ ];
 48 │ 
 49 │ export class GitError extends Error {
 50 │   constructor(message: string, readonly status: number | null, readonly args: readonly string[]) {
 51 │     super(message);
 52 │     this.name = "GitError";
 53 │   }
 54 │ }
 55 │ 
 56 │ /** A checkout (or a repository nested in one) whose Git directory the sandboxed agent could have planted. */
 57 │ export class UntrustedCheckoutError extends GitError {
 58 │   constructor(cwd: string, reason: string, args: readonly string[]) {
 59 │     super(`refusing to run Git in ${cwd}: it is not a trusted worktree of this repository (${reason})`, null, args);
 60 │     this.name = "UntrustedCheckoutError";
 61 │   }
 62 │ }
 63 │ 
 64 │ export interface GitResult { status: number | null; stdout: string; stderr: string; timedOut: boolean }
 65 │ 
 66 │ export interface GitOptions {
 67 │   /** Milliseconds before the child is killed (default 30 s). */
 68 │   timeoutMs?: number;
 69 │   /** Do not throw on a non-zero exit. */
 70 │   allowFailure?: boolean;
