 81 │ 
 82 │ /**
 83 │  * The agent runs in a sandbox that can write its worktree, `.git` pointer file and any nested repository included, but
 84 │  * nothing outside it. Git reads the configuration of whatever repository `.git` leads to; a planted one can carry
 85 │  * commands (`filter.*.clean`, `commit.gpgsign` with `gpg.program`) that would run on the host. A checkout is trusted only
 86 │  * when every `.git` file on the way up is a plain pointer to a Git directory OUTSIDE the outermost linked worktree
 87 │  * (outside what the agent can write) that points back at it (`gitdir` of a `<common>/worktrees/<name>` entry, or
 88 │  * `core.worktree` of a separate or submodule Git directory), and no repository with a real `.git` directory sits inside
 89 │  * a linked worktree. `gitDir`/`workTree` are the verified pair for the nearest `.git` file: Git is then run against them
 90 │  * directly, so a pointer rewritten after this check is not re-read.
 91 │  */
 92 │ /**
 93 │  * The path in a `.git` pointer file, read the way Git reads it: the content must start with `gitdir: `, only the
 94 │  * trailing line break is dropped, and nothing else is trimmed. A guard that trimmed would resolve a different directory
 95 │  * than Git does for `gitdir: x ` and could be shown a harmless one; such a pointer is refused instead.
 96 │  */
 97 │ export function parseGitfilePointer(content: string): string | undefined {
 98 │   if (!content.startsWith("gitdir: ")) return undefined;
 99 │   const target = content.slice("gitdir: ".length).replace(/\r?\n$/, "");
100 │   if (target === "" || target !== target.trim() || /[\0\r\n]/.test(target)) return undefined;
101 │   return target;
102 │ }
103 │ 
104 │ export function verifyCheckout(cwd: string): { reason?: string; gitDir?: string; workTree?: string } {
105 │   let start: string;
106 │   try { start = fs.realpathSync(cwd); } catch { return {}; }
107 │   const files: string[] = [];
108 │   const directories: string[] = [];
109 │   for (let dir = start; ; dir = path.dirname(dir)) {
110 │     try {
111 │       if (fs.lstatSync(path.join(dir, ".git")).isDirectory()) directories.push(dir); else files.push(dir);
112 │     } catch { /* no .git here */ }
113 │     if (path.dirname(dir) === dir) break;
114 │   }
115 │   const outer = files[files.length - 1];
116 │   if (!outer) return {}; // a plain repository (or none): not a sandbox-writable checkout
117 │   const planted = directories.find((dir) => inside(outer, dir));
118 │   if (planted) return { reason: `${planted} is a repository nested inside the linked worktree ${outer}` };
119 │   let pinned: { gitDir: string; workTree: string } | undefined;
120 │   for (const root of files) {
121 │     const dotGit = path.join(root, ".git");
122 │     try {
123 │       const stat = fs.lstatSync(dotGit);
124 │       if (stat.isSymbolicLink() || !stat.isFile() || stat.size > 4096) return { reason: `${dotGit} is not a plain pointer file` };
125 │       const target = parseGitfilePointer(fs.readFileSync(dotGit, "utf8"));
126 │       if (target === undefined) return { reason: `${dotGit} is not a well-formed gitdir pointer` };
127 │       const admin = fs.realpathSync(path.resolve(root, target));
128 │       if (inside(outer, admin)) return { reason: `${dotGit} leads into a repository inside the worktree itself` };
129 │       let pointsBack = false;
130 │       if (path.basename(path.dirname(admin)) === "worktrees") {
131 │         const common = fs.realpathSync(path.dirname(path.dirname(admin)));
132 │         if (inside(outer, common)) return { reason: `${dotGit} leads into a repository inside the worktree itself` };
133 │         pointsBack = fs.realpathSync(path.resolve(admin, fs.readFileSync(path.join(admin, "gitdir"), "utf8").trim())) === path.join(root, ".git");
134 │       } else {
135 │         const configured = /^\s*worktree\s*=\s*(.+?)\s*$/m.exec(fs.readFileSync(path.join(admin, "config"), "utf8"));
136 │         pointsBack = Boolean(configured) && fs.realpathSync(path.resolve(admin, configured![1])) === root;
137 │       }
138 │       if (!pointsBack) return { reason: `the Git directory behind ${dotGit} does not point back at it` };
139 │       pinned ??= { gitDir: admin, workTree: root };
140 │     } catch {
141 │       return { reason: `${dotGit} could not be verified` };
142 │     }
143 │   }
144 │   return pinned ?? {};
145 │ }
