147 │ /** `git submodule status` lines as {path, initialised}; a path may contain spaces. */
148 │ export function parseSubmoduleStatus(listing: string): Array<{ path: string; initialised: boolean }> {
149 │   const found: Array<{ path: string; initialised: boolean }> = [];
150 │   for (const line of listing.split("\n")) {
151 │     const match = /^(.)[0-9a-f]{40,64} (.*?)(?: \(.*\))?$/.exec(line);
152 │     if (match) found.push({ path: match[2], initialised: match[1] !== "-" });
153 │   }
154 │   return found;
155 │ }
