157 │ /** The reason `cwd` is not a trusted checkout (see `verifyCheckout`), or undefined. */
158 │ export function untrustedCheckoutReason(cwd: string): string | undefined {
159 │   return verifyCheckout(cwd).reason;
160 │ }
161 │ 
162 │ /**
163 │  * Whether a repository the agent could have planted sits below `dir`: a gitlink in the index or an untracked directory
164 │  * holding a `.git`. Git itself descends into submodules when it reports status, reading their configuration, so this
165 │  * runs before every status. Undefined when `dir` is not an agent-writable checkout or nothing is wrong.
166 │  */
167 │ export function nestedRepositoryReason(dir: string): string | undefined {
168 │   const own = verifyCheckout(dir);
169 │   if (own.reason) return own.reason;
170 │   if (!own.gitDir) return undefined;
171 │   const candidates = new Set<string>();
172 │   for (const entry of git(dir, ["ls-files", "-s", "-z"]).stdout.split("\0")) {
173 │     const match = /^160000 [0-9a-f]+ \d\t(.+)$/.exec(entry);
174 │     if (match) candidates.add(match[1]);
175 │   }
176 │   for (const entry of git(dir, ["ls-files", "-o", "--exclude-standard", "--directory", "-z"]).stdout.split("\0")) {
177 │     if (entry.endsWith("/")) candidates.add(entry.slice(0, -1));
178 │   }
179 │   for (const rel of candidates) {
180 │     const reason = verifyCheckout(path.join(dir, rel)).reason;
181 │     if (reason) return reason;
182 │   }
183 │   return undefined;
184 │ }
185 │ 
186 │ let hookEnvCache: { key: string; env: NodeJS.ProcessEnv } | undefined;
187 │ 
188 │ function baseEnv(): NodeJS.ProcessEnv {
189 │   // Computed per process-environment value: envWithoutConfiguredHooks spawns `git --version`.
190 │   const key = process.env.GIT_CONFIG_PARAMETERS ?? "";
191 │   if (!hookEnvCache || hookEnvCache.key !== key) {
192 │     hookEnvCache = { key, env: envWithoutConfiguredHooks(process.cwd(), SUPPRESSED_HOOK_EVENTS) };
193 │   }
194 │   const env: NodeJS.ProcessEnv = { ...hookEnvCache.env };
195 │   for (const name of SCRUBBED_ENV) delete env[name];
196 │   env.GIT_TERMINAL_PROMPT = "0";
197 │   env.LC_ALL = "C";
198 │   env.LANGUAGE = "C";
199 │   return env;
200 │ }
201 │ 
202 │ export function git(cwd: string, args: readonly string[], options: GitOptions = {}): GitResult {
203 │   const checkout = verifyCheckout(cwd);
204 │   if (checkout.reason) throw new UntrustedCheckoutError(cwd, checkout.reason, args);
205 │   const pin = checkout.gitDir ? ["--git-dir", checkout.gitDir, "--work-tree", checkout.workTree!] : [];
206 │   const result = spawnSync("git", [...PINNED_GIT_FLAGS, ...pin, ...args], {
207 │     cwd,
208 │     encoding: "utf8",
209 │     stdio: ["pipe", "pipe", "pipe"],
210 │     input: options.input ?? "",
211 │     env: { ...baseEnv(), ...(options.env ?? {}) },
212 │     timeout: options.timeoutMs ?? 30_000,
213 │     maxBuffer: options.maxBuffer ?? 32 * 1024 * 1024,
214 │   });
215 │   const timedOut = (result.error as NodeJS.ErrnoException | undefined)?.code === "ETIMEDOUT";
216 │   const out: GitResult = { status: result.status, stdout: result.stdout ?? "", stderr: result.stderr ?? "", timedOut };
217 │   if (result.error && !timedOut) throw new GitError(`git could not run: ${(result.error as Error).message}`, null, args);
218 │   if (!options.allowFailure && (timedOut || result.status !== 0)) {
219 │     const detail = timedOut ? "timed out" : redactSecrets(out.stderr.trim().split("\n")[0] ?? "").slice(0, 300);
220 │     throw new GitError(`git ${args[0] ?? ""} failed: ${detail || `exit ${result.status}`}`, result.status, args);
221 │   }
222 │   return out;
223 │ }
