225 │ /** `git ...` stdout, trimmed of one trailing newline. */
226 │ export function gitOut(cwd: string, args: readonly string[], options: GitOptions = {}): string {
227 │   return git(cwd, args, options).stdout.replace(/\n$/, "");
228 │ }

